/* ÇEVİRİ it · olay — arac/ceviri.py ile YAZILDI, elle düzenleme: py arac/ceviri.py uygula.
   Kayıt: id → [metin, kaynak_ozet] (olayda alan başına). Tasarım: denetim/CEVIRI-1103/TASARIM.md */
Ceviri.ekle("it","olay",{
"OLAYLAR:1299-01:0":{"b": ["Fondazione del beylik ottomano", "9f0b7c0a"], "d": ["L'inizio dell'autonomia di Osman Gazi, della tribù dei Kayı, nella regione di Söğüt e Domaniç è considerato per tradizione l'avvio della fondazione dello Stato ottomano; alcuni storici ritengono invece la vittoria di Bapheus del 1302 il vero punto di svolta. Grazie alla sua posizione sul confine bizantino, il beylik crebbe rapidamente in forza con le incursioni dei ghazi. In questo contesto di dissoluzione dell'eredità selgiuchide, Osman Gazi raccolse attorno a sé ahi, ghazi e turcomanni nomadi; il legame con lo sceicco Edebali è considerato il fondamento della legittimità spirituale del beylik. Altri luoghi annessi nella stessa data: İnegöl, Yarhisar.", "9d689d45"]},
"OLAYLAR:1326-04-06:0":{"b": ["Conquista di Bursa", "98c727fa"], "d": ["Bursa, tenuta sotto blocco per anni, si arrese a Orhan Gazi, che guidò la fase finale dell'assedio; la città divenne la prima grande capitale del beylik. Si narra che la notizia della conquista sia stata portata a Osman Gazi sul letto di morte; per sua volontà Osman Gazi fu sepolto a Bursa. In breve tempo la città fu dotata di moschee, imaret e madrase e divenne il modello dell'urbanistica ottomana delle origini.", "9ede6ee9"]},
"OLAYLAR:1331-03-02:0":{"b": ["Conquista di İznik", "a846a811"], "d": ["İznik (Nicea), uno dei più importanti centri bizantini in Anatolia, perduta ogni speranza di resistere dopo la vittoria di Pelekanon del 1329, si arrese a Orhan Gazi. Qui fu fondata la prima madrasa ottomana e studiosi come Dâvûd-i Kayserî vi iniziarono a insegnare; la città divenne il centro del sapere del primo periodo. La chiesa di Santa Sofia fu trasformata in moschea, un esempio precoce della tradizione della conquista.", "8fd3bfb5"]},
"OLAYLAR:1337-01-01:0":{"b": ["Conquista di İzmit", "06a35035"], "d": ["Con la caduta di İzmit (Nicomedia) anche l'ultima importante fortezza bizantina sulla sponda anatolica passò sotto il dominio ottomano; l'intera penisola di Kocaeli, fino alla riva opposta a Costantinopoli, divenne territorio ottomano. Il beylik, dominando così tutte le coste meridionali e orientali del Marmara, preparò le basi del passaggio in Rumelia.", "f677745c"]},
"OLAYLAR:1352-03-01:0":{"b": ["Fortezza di Çimpe — il passaggio in Rumelia", "c2f0a07d"], "d": ["Süleyman Paşa, figlio di Orhan Gazi, aveva fatto della fortezza di Çimpe, concessa durante la guerra civile bizantina, la propria base nel 1352; dopo il grande terremoto che nel marzo 1354 distrusse Gallipoli, le fortezze rimaste vuote furono rapidamente fortificate e la penisola divenne una testa di ponte ottomana stabile. Sostenuto dall'insediamento di popolazione turcomanna condotta dall'Anatolia, questo passo segna l'inizio di una presenza ottomana sul continente europeo destinata a superare i 550 anni.", "4857333a"]},
"OLAYLAR:1361-05-05:0":{"b": ["Conquista di Edirne", "2f54ebb0"], "d": ["La presa di Edirne (Adrianopoli), città chiave della Tracia, determinò la base principale e la direzione delle conquiste balcaniche; la data della conquista è controversa nelle fonti, tra il 1361 e il 1369. Poco dopo la città fu fatta capitale, annunciando lo spostamento del baricentro dello Stato verso la Rumelia; rimase capitale per circa 90 anni, fino alla conquista di Costantinopoli.", "25bd644f"]},
"OLAYLAR:1362-03:0":{"b": ["Murad I salì al trono", "f8d48a26"], "d": ["Murad I (Hüdavendigâr), salito al trono con la morte di Orhan Gazi, nei 27 anni del suo regno portò lo Stato da beylik di frontiera a ossatura di impero. Con il sistema del pençik fu posta la base del corpo dei Giannizzeri, il sistema del timar fu esteso, fu istituito il Beylerbeylik di Rumelia e fu rafforzata l'istituzione del vizirato. Le conquiste balcaniche divennero sotto di lui una politica statale sistematica.", "d463078a"]},
"OLAYLAR:1389-06-15:0":{"b": ["Prima battaglia di Kosovo — il martirio di Murad I", "10b8ddc9"], "d": ["L'alleanza balcanica guidata dal knez Lazar fu sconfitta in modo decisivo nella Piana del Kosovo; la Serbia entrò sotto la sovranità ottomana. Murad I, che percorreva il campo di battaglia, fu pugnalato dal nobile serbo Miloš Obilić e cadde martire: è l'unico sultano ottomano morto sul campo di battaglia. Nell'accampamento gli succedette Yıldırım Bayezid; il fratello Yakub Çelebi fu fatto strangolare, uno dei primi esempi noti di fratricidio dinastico.", "153449fe"]},
"OLAYLAR:1396-09-25:0":{"b": ["Vittoria di Nicopoli", "75716e96"], "d": ["Il grande esercito crociato, riunito per l'appello del re ungherese Sigismondo e al quale parteciparono anche cavalieri francesi e borgognoni, fu duramente sconfitto da Yıldırım Bayezid davanti a Nicopoli, sulle rive del Danubio. La vittoria consolidò il dominio ottomano sulla Bulgaria; in Europa per una generazione non fu possibile organizzare una grande crociata.", "0d06e36c"]},
"OLAYLAR:1402-07-28:0":{"b": ["Battaglia di Ankara — inizio del Fetret Devri", "b4a99d96"], "d": ["Nella pesante sconfitta subita nella piana di Çubuk contro l'esercito di Tamerlano, Yıldırım Bayezid fu fatto prigioniero e morì in prigionia pochi mesi dopo. Tamerlano fece rivivere i beylik anatolici; i territori ottomani furono spartiti tra i figli di Bayezid e iniziò una lotta per il trono destinata a durare 11 anni (Fetret Devri). Questo periodo, la crisi più grave dalla fondazione dello Stato, impresse nella memoria ottomana l'importanza della struttura centralizzata. Altri insediamenti perduti nella stessa data: Datça, Marmaris, Fethiye (Makri), Söke, Kütahya, Afyon, Isparta, Manisa, Aydın, Denizli, Muğla, Antalya, Konya, Karaman, Kayseri, Kastamonu, Bartın, Safranbolu, Samsun, Sivas, Malatya, Beyşehir, Sivrihisar, Kırşehir, Çorum, Çankırı, Yenişehir (Bursa), İnegöl, Aydos Kalesi, Geyve, Köprühisar (Yenişehir), Marmaracık, Akhisar (Pamukova), Mekece, Kestel, Ulubat, Harmankaya, Akyazı, İmralı Adası, Kandıra, Mudanya, Yalova, Karamürsel, Armutlu, Gemlik (Kios), Söğüt, Bilecik, Eskişehir, Bursa, İznik, İzmit, Balıkesir, Çanakkale, Bergama, Amasya, Tokat, Çorlu, Lüleburgaz, Malkara, Keşan, İpsala, Kilitbahir, Çirmen, Eski Zağra (Stara Zagora), Tatarpazarcığı, İhtiman, Köstendil, Petriç, Nevrokop (Gotse Delçev), Drama, Gelibolu, Çimpe, Edirne, Dimetoka, Kırklareli, Tekirdağ, Filibe, Sofya, Niş, Vidin, Tırnova, Varna, Şumnu, Silistre, Niğbolu, Rusçuk, Selanik, Serez, Kavala, Üsküp, Manastır, Ohri, Yenişehir (Larissa), Tırhala, İzdin (Lamia), Plevne, Gümülcine, Biga, Domaniç, Kulacahisar, Karacahisar, Yarhisar, Dimbos, Kite (Kete), Lefke (Osmaneli), Leblebicihisar, Karaçepüş, Karatigin, Absu (Hypsu), Adranos (Orhaneli), Pelekanon (Eskihisar), Gebze, Hereke, Samandıra, Kirmasti (M.Kemalpaşa), Mihaliç (Karacabey), Köstence, Gölyazı (Apollonia).", "d34e55d5"]},
"OLAYLAR:1413-07-05:0":{"b": ["Çelebi Mehmed ricostituì l'unità", "03413dfd"], "d": ["Sconfitto Mûsâ Çelebi a Çamurlu nel regolamento di conti finale tra i fratelli, Mehmed I riunì i territori del paese sotto un'unica amministrazione; per questo è considerato il «secondo fondatore dello Stato». Durante il suo regno la struttura statale logorata fu riparata, i rapporti con i beylik anatolici furono riequilibrati e in Rumelia fu seguita una cauta politica di pace.", "d8f535c2"]},
"OLAYLAR:1416-05-01:0":{"b": ["Rivolta dello sceicco Bedreddin", "e0a072ca"], "d": ["Il movimento religioso e sociale sviluppatosi attorno allo sceicco Bedreddin, grande giurista e mistico che era stato kazasker durante il Fetret Devri, esplose in contemporanea con le rivolte di Börklüce Mustafa a Karaburun e di Torlak Kemal a Manisa. Le rivolte furono represse nel sangue; Bedreddin, catturato nel Deliorman, fu giustiziato a Serez. L'evento lasciò una traccia profonda nella letteratura e nella storiografia come la più antica grande rivolta sociale e mahdista della storia ottomana.", "1cf72ec4"]},
"OLAYLAR:1444-11-10:0":{"b": ["Vittoria di Varna", "f739eedc"], "d": ["L'esercito crociato ungaro-polacco, che aveva rotto il trattato di Seghedino e marciava verso sud, fu annientato a Varna da Murad II, tornato alla testa dell'esercito dopo l'abdicazione; il giovane re Ladislao III morì sul campo di battaglia. La vittoria eliminò l'ultima grande possibilità di intervento esterno volto a liquidare la presenza ottomana nei Balcani e mise al sicuro la strada verso la conquista di Costantinopoli.", "43adf0fb"]},
"OLAYLAR:1448-10-17:0":{"b": ["Seconda battaglia di Kosovo", "ebe0b662"], "d": ["L'esercito di Giovanni Hunyadi, che voleva vendicare Varna, fu sconfitto in modo decisivo da Murad II in tre giorni di aspra battaglia. È l'ultima grande battaglia campale intrapresa dai crociati contro gli Ottomani nei Balcani; con la vittoria il dominio ottomano a sud del Danubio si consolidò in modo ormai irreversibile.", "ea3ae23b"]},
"OLAYLAR:1453-05-29:0":{"b": ["Conquista di Costantinopoli", "583d5e3e"], "d": ["Dopo un assedio durato cinquantaquattro giorni (6 aprile–29 maggio 1453), la mattina del 29 maggio l'esercito ottomano superò le mura ed entrò in città; l'ultimo imperatore, Costantino XI, morì nei combattimenti e l'Impero romano d'Oriente, vecchio di 1100 anni, scomparve dalla storia. Il giovane sultano assunse il titolo di «Fâtih», fece della città la capitale e trasformò Santa Sofia in moschea; la città fu presto rianimata da insediamenti e ricostruzioni. Secondo il TDV, Silivri e Vize furono conquistate definitivamente solo nel 1453; secondo la voce Limni del TDV, l'isola entrò sotto l'amministrazione ottomana subito dopo la conquista e fu lasciata alla famiglia Gattilusio a condizione di un tributo. Nell'atlante Silivri, Vize e Limni sono registrate in questo giorno come passate da Bisanzio agli Ottomani (Limni tributaria). La fusione di cannoni giganteschi, il trasporto delle navi via terra e lo schieramento d'assedio davanti alle mura sono considerati il vertice dell'ingegneria militare dell'epoca. Nella storiografia europea la conquista è tra le date simbolo della fine del Medioevo.", "d4b39486"]},
"OLAYLAR:1461-08-15:0":{"b": ["Conquista di Trebisonda", "15f52403"], "d": ["Al termine della difficile campagna del Mar Nero condotta da Mehmed il Conquistatore simultaneamente con esercito e flotta, l'Impero greco di Trebisonda si arrese; con la liquidazione di quest'ultimo residuo del mondo bizantino in Anatolia, l'intera costa meridionale del Mar Nero entrò sotto il dominio ottomano. La fine della dinastia dei Comneni rafforzò la pretesa del Conquistatore di essere «sovrano di due mari e due terre». Altri luoghi annessi nella stessa data: Giresun, Rize.", "ca6ead13"]},
"OLAYLAR:1473-01-01:0":{"b": ["Conquista definitiva di Silifke — spezzata l'ultima resistenza dei Karamanidi", "d988bee4"], "d": ["La fortezza di Silifke si era arresa una volta a Gedik Ahmed Paşa nel 1472, ma nello stesso anno il karamanide Kasım Bey, con l'aiuto della flotta crociata nel Mediterraneo, l'aveva ripresa. Dopo la vittoria di Otlukbeli, il Conquistatore incaricò suo figlio e Gedik Ahmed Paşa di impadronirsi definitivamente della regione; con l'aiuto degli antichi artiglieri ottomani il deposito di polvere fu incendiato e la fortezza cadde rapidamente. Così fu spezzata l'ultima resistenza dei Karamanidi sulle montagne del Taşeli e dell'İçel; la liquidazione del beylik sarebbe stata completata nel 1474.", "e9814184"]},
"OLAYLAR:1473-08-11:0":{"b": ["Battaglia di Otlukbeli", "42c7194e"], "d": ["Uzun Hasan, sovrano degli Aqquyunlu divenuto una grande potenza a oriente e alleato di Venezia, fu duramente sconfitto a Otlukbeli dall'esercito del Conquistatore, dotato di armi da fuoco. La vittoria consolidò la supremazia ottomana in Anatolia e fu anche una prova precoce della superiorità di un esercito centrale che impiegava cannoni e fucili contro un esercito classico. Secondo la voce Gümüşhane del TDV, la città era sotto il dominio degli Aqquyunlu dal 1467; tale dominio terminò con la sconfitta di Otlukbeli e Gümüşhane passò definitivamente sotto il dominio ottomano.", "63e0811f"]},
"OLAYLAR:1475-06-06:0":{"b": ["La Crimea passa sotto la protezione ottomana", "44e3f7c8"], "d": ["La flotta al comando di Gedik Ahmed Paşa conquistò le città della costa meridionale della Crimea, a cominciare da Kefe, in mano ai Genovesi; queste coste furono rese sancak direttamente ottomano. Il Khanato di Crimea, con Mengli Giray, divenne invece uno Stato vassallo privilegiato che riconosceva la sovranità ottomana e per tre secoli fu un pilastro della politica settentrionale; il Mar Nero si trasformò di fatto in un mare interno ottomano. Altri luoghi annessi nella stessa data: Bahçesaray, Kerç, Azak.", "a3448d71"]},
"OLAYLAR:1481-05-03:0":{"b": ["Morte del Conquistatore — la questione del principe Cem", "190ecf01"], "d": ["Alla morte improvvisa del Conquistatore durante la campagna salì al trono Bayezid II; il fratello Cem Sultan, avanzando pretese al sultanato, fece leggere la khutba e coniare moneta a suo nome a Bursa. Sconfitto, si rifugiò prima presso i Mamelucchi, poi presso i cavalieri di Rodi; divenuto nelle mani dei cavalieri e del papato una carta di scambio della diplomazia europea, Cem morì a Napoli nel 1495. Questo episodio costrinse la politica estera ottomana alla cautela per quindici anni.", "7e488d7b"]},
"OLAYLAR:1514-08-23:0":{"b": ["Vittoria di Çaldıran", "fea64ebb"], "d": ["Selim I il Severo, volendo risolvere alla radice la minaccia creata in Anatolia dalla propaganda safavide, sconfisse duramente nella piana di Çaldıran l'esercito dello shah Ismail grazie alla superiorità di cannoni e fucili. Si entrò a Tabriz; l'Anatolia orientale e sud-orientale e la linea Mosul-Diyarbakır furono incorporate nell'amministrazione ottomana. Con l'impegno di İdrîs-i Bitlisî, il legame dei principi curdi con gli Ottomani stabilì il quadro del confine orientale per i secoli a venire.", "67b03a64"]},
"OLAYLAR:1516-08-24:0":{"b": ["Vittoria di Marj Dabiq", "07d254d3"], "d": ["L'esercito mamelucco fu disperso in poche ore a Marj Dabiq, a nord di Aleppo; l'anziano sultano Qansuh al-Ghawri morì durante la battaglia. Con la vittoria che spalancò le porte di Aleppo e Damasco, Siria, Libano e Palestina passarono sotto il dominio ottomano; si aprì la strada alla campagna d'Egitto che avrebbe posto fine al Sultanato mamelucco.", "c4b15f39"]},
"OLAYLAR:1517-01-22:0":{"b": ["Ridaniye — conquista dell'Egitto e califfato", "caf378d6"], "d": ["L'esercito ottomano, attraversato rapidamente il deserto del Sinai, sfondò a Ridaniye la linea difensiva di Tumanbay ed entrò al Cairo; Tumanbay, che continuava la resistenza, fu catturato e giustiziato e il Sultanato mamelucco scomparve dalla storia. Egitto, Hegiaz e città sante entrarono sotto il dominio ottomano; il califfo abbaside e le sacre reliquie furono portati a Costantinopoli. Con il passaggio del califfato alla dinastia ottomana, i sultani assunsero la pretesa di guida del mondo islamico; il controllo della Via delle Spezie procurò inoltre all'impero grandi entrate. Altri luoghi annessi nella stessa data: Akkâ, Maan, Sayda, Kerak.", "a0cc8fdc"]},
"OLAYLAR:1520-09-30:0":{"b": ["Solimano il Legislatore salì al trono", "f6512269"], "d": ["Il regno di 46 anni di Solimano I, salito al trono come unico figlio maschio alla morte di Selim il Severo, è considerato l'apice politico, militare, giuridico e culturale dell'impero. I kanunname, che sistematizzarono il diritto consuetudinario, gli valsero il titolo di «Kanunî» (il Legislatore); in Occidente fu chiamato «il Magnifico». Le opere dell'architetto Sinan, l'età d'oro della letteratura di divan e la supremazia della flotta nel Mediterraneo sono i simboli di questo periodo.", "cda7a2fb"]},
"OLAYLAR:1521-08-29:0":{"b": ["Conquista di Belgrado", "59ef5cec"], "d": ["Belgrado, che il Conquistatore non aveva potuto prendere nel 1456 e che era considerata la «chiave dell'Europa centrale», cadde nella prima campagna di Solimano dopo un assedio alla confluenza di Danubio e Sava. La linea difensiva meridionale dell'Ungheria crollò; con questa conquista si aprì la porta della campagna in Europa centrale, che si estese a Mohács cinque anni dopo e all'annessione di Buda vent'anni dopo.", "69dbb7cc"]},
"OLAYLAR:1522-12-21:0":{"b": ["Conquista di Rodi", "807bbb1e"], "d": ["Rodi, base dei cavalieri di San Giovanni che minacciavano le rotte marittime del Mediterraneo orientale e la via dei pellegrini, si arrese per patto dopo un sanguinoso assedio durato mesi; ai cavalieri fu permesso di lasciare liberamente l'isola (si sarebbero poi stabiliti a Malta). Fu assicurata la sicurezza delle coste anatoliche e la linea marittima Costantinopoli-Egitto passò sotto ininterrotto controllo ottomano.", "aeedfb16"]},
"OLAYLAR:1526-08-29:0":{"b": ["Battaglia di Mohács", "f3418b0d"], "d": ["L'esercito ungherese fu annientato nella piana di Mohács in circa due ore dal fuoco dell'artiglieria e dalla superiorità di manovra; il re Luigi II morì in una palude mentre fuggiva. Mohács, una delle grandi battaglie campali vinte più rapidamente nella storia ottomana, pose di fatto fine al regno ungherese indipendente e aprì in Europa centrale l'epoca della rivalità ottomano-asburgica.", "48967894"]},
"OLAYLAR:1529-09-27:0":{"b": ["Primo assedio di Vienna", "dc49ea4f"], "d": ["Nella campagna organizzata contro le mire asburgiche sul trono ungherese l'esercito ottomano assediò Vienna; per l'abbandono dei cannoni pesanti lungo la strada, l'inverno precoce e le difficoltà di vettovagliamento l'assedio fu tolto dopo tre settimane. Pur non essendo stata presa la città, l'influenza ottomana sull'Ungheria fu mantenuta; le porte di Vienna indicarono il limite dell'accesso logistico dell'impero in Europa centrale.", "a49fc760"]},
"OLAYLAR:1534-12-04:0":{"b": ["Conquista di Baghdad — campagna dei Due Iraq", "897092c3"], "d": ["Nella campagna condotta sui «due Iraq» (Iraq arabo e Iraq persiano) si entrò prima a Tabriz, poi senza combattere a Baghdad; la presa dell'antica capitale degli Abbasidi diede al sovrano ottomano grande prestigio nel mondo islamico. Fu restaurato il mausoleo dell'Imam-ı Âzam Abu Hanifa; con l'annessione di Baghdad e Bassora i territori ottomani raggiunsero il Golfo Persico. Altri luoghi annessi nella stessa data: Kerkük, Kerbelâ.", "f3f80434"]},
"OLAYLAR:1538-09-28:0":{"b": ["Vittoria navale di Prevesa", "30dc0f97"], "d": ["La flotta crociata costituita sotto la guida del papa, benché numericamente superiore, fu dispersa al largo di Prevesa dalla tattica di Barbarossa, che sfruttò con maestria vento e costa; Andrea Doria abbandonò il campo di battaglia. La vittoria stabilì una supremazia navale ottomana incontrastata nel Mediterraneo destinata a durare circa 33 anni; è la data simbolo della Giornata della Marina nella tradizione marinara turca. Altri luoghi annessi nella stessa data: Aden, Bender.", "0411d92f"]},
"OLAYLAR:1541-08-29:0":{"b": ["Annessione di Buda — l'Ungheria provincia ottomana", "db53b244"], "d": ["Partito in campagna per l'assedio asburgico di Buda, Solimano, dopo aver liberato la città, pose l'Ungheria centrale sotto amministrazione ottomana diretta istituendo il Beylerbeylik di Buda; la Transilvania fu invece resa principato autonomo vassallo degli Ottomani. Questo assetto dell'Ungheria divisa in tre durò circa 150 anni e costituì l'ossatura stabile del governo ottomano in Europa centrale.", "1eb63e33"]},
"OLAYLAR:1555-05-29:0":{"b": ["Pace di Amasya", "a5afe0d1"], "d": ["È il primo trattato di pace ufficiale che pose fine alle guerre ottomano-safavidi durate anni. Baghdad e l'Iraq rimasero agli Ottomani, il confine dell'Anatolia orientale fu per la prima volta riconosciuto reciprocamente; i Safavidi si impegnarono a fermare la propaganda sciita nel territorio ottomano e gli Ottomani a garantire la sicurezza di transito dei pellegrini iraniani. Il trattato fu il primo esempio del quadro giuridico delle relazioni tra i due Stati.", "220b198f"]},
"OLAYLAR:1566-09-07:0":{"b": ["Szigetvár — la morte di Solimano", "e2917ed2"], "d": ["Solimano, settantaduenne, morì nella sua tenda pochi ore prima della caduta della fortezza di Szigetvár, che assediava nella sua tredicesima campagna; Sokullu Mehmed Paşa nascose la morte per settimane perché l'esercito non si disperdesse. La fortezza fu presa, ma lo Stato aveva perso il sultano dal regno più lungo e più splendido; salì al trono il figlio Selim II e il peso dei grandi visir nell'amministrazione dello Stato cominciò ad aumentare.", "62c468a1"]},
"OLAYLAR:1571-08-01:0":{"b": ["Conquista di Cipro", "e364a2b3"], "d": ["Nel 1570 fu effettuato lo sbarco a Cipro, sotto dominio veneziano; Nicosia cadde rapidamente, mentre Famagosta si arrese solo nell'agosto 1571, dopo un assedio di undici mesi. L'isola, cruciale per la sicurezza delle rotte commerciali e dei pellegrinaggi del Mediterraneo orientale, fu organizzata come beylerbeylik e vi fu insediata popolazione dall'Anatolia; la conquista fu anche il pretesto della grande alleanza crociata che sarebbe giunta a Lepanto.", "6dcfdc0f"]},
"OLAYLAR:1571-10-07:0":{"b": ["Sconfitta di Lepanto (İnebahtı)", "6a1d44a9"], "d": ["La flotta crociata, unitasi per la conquista di Cipro, colse la flotta ottomana nel golfo di Lepanto e ne distrusse la maggior parte; il kapudan paşa Müezzinzâde Ali Paşa cadde martire e si salvò solo la squadra di Uluç Ali. Dopo il disastro il gran visir Sokullu Mehmed Paşa nominò Uluç Ali Paşa kapudan paşa affidandogli il compito di ricostituire la flotta dispersa e avviò la costruzione di una nuova flotta in tutti gli arsenali, da Costantinopoli ad Alanya; tuttavia la supremazia assoluta nel Mediterraneo era stata psicologicamente scossa.", "4cb5c93e"]},
"OLAYLAR:1596-10-26:0":{"b": ["Battaglia di Mezőkeresztes (Haçova)", "da308ec5"], "d": ["Nella più grande battaglia campale della Lunga Guerra (1593–1606), l'esercito guidato personalmente da Mehmed III, nel momento in cui stava per disperdersi, si riorganizzò per l'esortazione di Hoca Sâdeddin Efendi e travolse l'esercito asburgico. È considerata l'ultima grande battaglia campale classica vinta dagli Ottomani; tuttavia il fatto che non abbia mutato l'andamento generale della guerra fu visto anche come segno del logoramento del sistema militare.", "77f2a384"]},
"OLAYLAR:1606-11-11:0":{"b": ["Pace di Zsitvatorok", "39c01142"], "d": ["Con il trattato che pose fine alla logorante guerra di tredici anni, il sovrano asburgico fu per la prima volta considerato pari al sultano con il titolo di «imperatore romano» e il tributo annuale fu abolito. Le perdite territoriali furono quasi nulle; ma questo mutamento del linguaggio diplomatico è letto come il simbolo della fine della pretesa ottomana di assoluta superiorità nei confronti dell'Europa.", "99a455e7"]},
"OLAYLAR:1639-05-17:0":{"b": ["Trattato di Qasr-ı Şirin", "c1acf3af"], "d": ["Il trattato firmato dopo la riconquista di Baghdad da parte di Murad IV (1638) pose fine a oltre un secolo di guerre ottomano-safavidi. Baghdad e l'Iraq rimasero definitivamente agli Ottomani, Erevan fu lasciata ai Safavidi; la linea tracciata, con piccole modifiche, divenne la base dell'attuale confine turco-iraniano ed è considerata uno dei confini più longevi del mondo. Il trattato lasciò agli Ottomani Bedre, Cessân, Mendelî, Derteng e Derne; la fortezza di Zencir sul confine sarebbe stata demolita, i villaggi a ovest di essa sarebbero rimasti agli Ottomani, quelli a est all'Iran. L'area intorno alla fortezza di Zalim presso Şehrizor e Kızılca Kale rimasero agli Ottomani, Avroman e Mihriban all'Iran; le fortezze di Kotur, Mâkû e Mağazberd sarebbero state demolite da entrambe le parti.", "c2d59f3f"]},
"OLAYLAR:1669-09-06:0":{"b": ["Completata la conquista di Creta", "e0d85604"], "d": ["L'assedio di Candia, ultimo atto della guerra di Creta iniziata nel 1645, si concluse con la determinata campagna triennale di Fâzıl Ahmed Paşa; il comandante veneziano Morosini consegnò la città con un trattato. La lotta, durata circa un quarto di secolo, è registrata come il più lungo assedio della storia ottomana; anche l'ultima grande fortezza latina del Mediterraneo orientale passò sotto il dominio ottomano. Le tre piccole fortezze rocciose sulla costa settentrionale dell'isola — Suda, Spinalonga e Grabusa — rimasero ancora ai Veneziani; poiché sorgono su isolotti separati, sulla mappa non possono essere mostrate separatamente dal resto di Creta.", "314efa97"]},
"OLAYLAR:1672-10-18:0":{"b": ["Pace di Buczacz — i confini più estesi", "b17b6e5a"], "d": ["Con la pace di Buczacz, firmata dopo la conquista di Kamianets nella campagna contro la Polonia, la Podolia fu annessa agli Ottomani e una parte dell'Ucraina fu posta sotto protezione. L'impero raggiunse così i suoi confini più ampi in Europa; questo punto è considerato l'apice e allo stesso tempo l'ultimo anello dell'epoca dell'espansione.", "6d489670"]},
"OLAYLAR:1683-09-12:0":{"b": ["Disfatta del secondo assedio di Vienna", "7d889252"], "d": ["L'assedio di Vienna di due mesi condotto da Merzifonlu Kara Mustafa Paşa si trasformò in disfatta per l'improvviso colpo scagliato dalle colline del Kahlenberg dal re di Polonia Jan Sobieski; l'esercito si ritirò abbandonando i bagagli e Merzifonlu fu giustiziato a Belgrado. La guerra con la Lega Santa formatasi dopo la vittoria durò 16 anni; questa disfatta è indicata come il momento d'inizio del grande declino nella storia ottomana.", "88ceb19f"]},
"OLAYLAR:1692-01-01:0":{"b": ["Conquista della fortezza di Grabusa — una delle fortezze rocciose di Creta rimaste ai Veneziani", "3ddf9eeb"], "d": ["Sebbene con la resa di Candia nel 1669 la conquista di Creta fosse considerata in gran parte completata, la fortezza insulare rocciosa di Grabusa, all'estremità nord-occidentale dell'isola, rimase in mano veneziana per altri ventitré anni. Con la sua presa nel 1692 fu eliminato uno dei tre residui veneziani a Creta; Suda e Spinalonga avrebbero atteso la campagna di Morea del 1715.", "05e94fe9"]},
"OLAYLAR:1699-01-26:0":{"b": ["Pace di Karlowitz — la prima grande perdita territoriale", "8f7e2546"], "d": ["Con Karlowitz, che pose fine a sedici anni di guerre con la Lega Santa, Ungheria e Transilvania furono lasciate all'Austria, la Podolia alla Polonia, la Morea e le coste della Dalmazia a Venezia. Per la prima volta nella storia ottomana un territorio di tale entità andava perduto a tavolino e in modo permanente; il trattato è considerato il documento d'avvio della nuova epoca in cui l'impero passò sulla difensiva di fronte all'Europa, ed è anche una svolta della storia della diplomazia ottomana. Insediamenti che nello stesso giorno cambiano mano nell'atlante: Kostajnica e Jasenovac (dagli Ottomani agli Asburgo; il testo del trattato lascia Castanoviz nelle mani dell'imperatore, il giorno della consegna di Jasenovac non è nella fonte, è stato scritto il giorno del trattato) e Preveza (da Venezia agli Ottomani; TDV karlofca: secondo la disposizione firmata il 24 Receb 1110 / 26 gennaio 1699 furono restituiti i luoghi occupati da Venezia a nord del golfo di Lepanto). L'atlante assegna inoltre Kostayniçe (Kostajnica) e Jasenovaç al lato asburgico, Uman e Vinnitsa in Ucraina della riva destra dagli Ottomani alla Polonia (TDV merzifonlu-kara-mustafa-pasa; IEU Vinnytsia: dominio turco 1672-99) e Nadin in Dalmazia a Venezia (il giorno di consegna specifico dell'insediamento non è nella fonte, è stato scritto il giorno del trattato; gli estremi del periodo di Nadin non sono verificati con la fonte — approssimazione dichiarata). Anche Vonitsa, a nord del golfo di Lepanto, viene restituita da Venezia agli Ottomani (TDV karlofca); in Dalmazia Vrana (Urana) è tra i luoghi rimasti a Venezia (estremo del periodo non verificato — dichiarato).", "0909e24e"]},
"OLAYLAR:1711-07-19:0":{"b": ["Vittoria del Prut", "2583572f"], "d": ["Nella guerra scoppiata per la questione del re di Svezia, rifugiatosi presso gli Ottomani dopo la sconfitta di Poltava, l'esercito dello zar Pietro I, accerchiato sulle rive del Prut, dovette arrendersi. Con il trattato firmato Azov fu restituita; la decisione di non annientare l'esercito e di lasciare libero lo zar è entrata nella storia come decisione discussa fino a oggi.", "ce9c2996"]},
"OLAYLAR:1715-01-01:0":{"b": ["Conquista delle fortezze di Suda e Spinalonga — cancellata l'ultima traccia veneziana a Creta", "7261f7ba"], "d": ["Ventitré anni dopo la caduta di Grabusa nel 1692, con una diramazione della campagna di Morea furono conquistate anche Suda e Spinalonga, gli ultimi due capisaldi veneziani a Creta. Così la conquista di Creta, iniziata nel 1645, fu completata dopo quarantasei anni fino all'ultimo centimetro dell'isola.", "d2044cae"]},
"OLAYLAR:1730-09-25:0":{"b": ["Rivolta di Patrona Halil", "100941a4"], "d": ["L'insuccesso sul fronte persiano, le tasse e la collera per il lusso della cerchia di palazzo si trasformarono in una grande insurrezione guidata dal bagnino Patrona Halil. Il gran visir İbrahim Paşa fu ucciso, Ahmed III fu deposto e l'Età dei Tulipani terminò; il fatto che i ribelli dominassero la città per mesi mostrò in modo impressionante la fragilità dell'autorità centrale.", "d87eea77"]},
"OLAYLAR:1739-09-18:0":{"b": ["Pace di Belgrado — la riconquista di Belgrado, Smederevo e della Serbia settentrionale", "ba7f8e46"], "d": ["Al termine della guerra condotta su due fronti contro Austria e Russia (1736–1739), Belgrado e la Serbia settentrionale furono riprese; la Russia accettò di smilitarizzare Azov e di non mantenere una flotta nel Mar Nero. Considerato l'ultimo grande successo della diplomazia e dell'esercito ottomano del XVIII secolo, il trattato procurò all'impero un periodo di pace di un quarto di secolo. Altri insediamenti che nello stesso giorno nell'atlante tornano dall'Austria agli Ottomani: Hisarcık (Grocka) (catena dell'abi-merkez di Belgrado; TDV belgrad), Krayova (Craiova), Rimnik (Râmnicu Vâlcea) e Turnu Severin (ritorno della Piccola Valacchia agli Ottomani, nel vassallaggio della Valacchia). Bosna Brod (Bosanski Brod) e Bosna Dubiça (Bosanska Dubica), sulla fascia della Sava, tornano invece agli Ottomani nell'atlante il 28 settembre 1739 (TDV bosna-hersek; TDV mahmud-i--osmanli: 28 settembre 1739). Anche Tırgu Jiu, nella Piccola Valacchia, torna agli Ottomani nello stesso giorno.", "118d49db"]},
"OLAYLAR:1770-07-06:0":{"b": ["Incursione di Çeşme", "840b30bd"], "d": ["La flotta russa, uscita nel Mediterraneo con l'appoggio degli Inglesi, assalì con brulotti la flotta ottomana rifugiata nel porto di Çeşme e la incendiò quasi per intero. La Russia apparve per la prima volta nel Mediterraneo come grande potenza navale; il disastro fu uno dei colpi che determinarono il destino della guerra conclusasi con Küçük Kaynarca nel 1774 e rese evidente la necessità di una riforma radicale della flotta.", "5b133a56"]},
"OLAYLAR:1774-07-21:0":{"b": ["Trattato di Küçük Kaynarca", "2776dcdb"], "d": ["Con Küçük Kaynarca, che pose fine alla guerra del 1768–1774 ed è considerato uno dei trattati più gravi della storia ottomana, fu concessa l'«indipendenza» al Khanato di Crimea — in pratica fu creata una sfera d'influenza russa. La Russia si insediò sulla costa del Mar Nero e ottenne il diritto di passaggio dagli Stretti per le navi mercantili e un'ambasciata permanente a Costantinopoli; la vaga clausola di protezione sui sudditi ortodossi aprì la porta ai pretesti di intervento del secolo successivo. Per la prima volta un territorio a popolazione musulmana veniva sottratto al dominio ottomano.", "b677ebfc"]},
"OLAYLAR:1783-04-19:0":{"b": ["Annessione della Crimea alla Russia", "bdf6faa8"], "d": ["La Crimea «indipendente» creata da Küçük Kaynarca, con il pretesto dei disordini sotto l'ultimo khan Şahin Giray, fu annessa alla Russia con il manifesto di Caterina II. La partnership ottomano-crimeana di tre secoli finì; la perdita delle steppe settentrionali eliminò la profondità difensiva di Costantinopoli e avviò la prima grande ondata di migrazione di decine di migliaia di Tatari di Crimea verso le terre ottomane. In questo giorno la penisola di Crimea (Aluşta, Kefe, Sudak, Yalta, Balaklava, İnkirman, Mankup, Arabat) fu annessa alla Russia; Taman e Kuban passarono alla Russia con la stessa annessione (TDV Kırım: 8 aprile 1783 giuliano = 19 aprile gregoriano).", "aa59d3e1"]},
"OLAYLAR:1789-04-07:0":{"b": ["Selim III e il Nizâm-ı Cedîd", "d53aec21"], "d": ["Selim III, salito al trono in piena guerra, vedendo che le sconfitte erano strutturali, avviò un ampio programma di riforme sotto il nome di «Nizâm-ı Cedîd» (Nuovo Ordine): un nuovo esercito addestrato all'europea, un tesoro separato per finanziarlo (Îrâd-ı Cedîd), il rafforzamento delle scuole di ingegneria e le prime ambasciate permanenti nelle capitali europee. Il programma è considerato l'inizio della moderna tradizione riformatrice turca; ma per la resistenza dei corpi e degli âyân sarebbe stato abbattuto nel 1807.", "87394990"]},
"OLAYLAR:1798-06-12:0":{"b": ["Liquidazione dei cavalieri di Malta — tappa della flotta francese lungo la rotta", "d62f901d"], "d": ["La flotta francese diretta in Egitto fece scalo a Malta, sul suo percorso; i cavalieri di San Giovanni (di Malta) consegnarono l'isola senza grande resistenza. L'ultima fortezza dell'ordine cavalleresco, cacciato da Rodi nel 1522 e stabilitosi qui, finì così. Malta sarebbe passata all'Inghilterra due anni dopo, mentre Napoleone si diresse dall'isola direttamente ad Alessandria.", "aac1fe49"]},
"OLAYLAR:1798-07-01:0":{"b": ["Occupazione dell'Egitto da parte di Napoleone", "93fede5f"], "d": ["L'esercito del generale Bonaparte sbarcò ad Alessandria e occupò l'Egitto; questa spedizione, mirante alla via dell'India dell'Inghilterra, fu il primo attacco diretto di una potenza europea ai territori centrali ottomani. L'incursione di Nelson ad Abukir e la difesa di Acri di Cezzâr Ahmed Paşa spezzarono la marcia francese; l'occupazione terminò nel 1801, ma nel vuoto lasciato iniziarono l'ascesa di Mehmed Ali Paşa di Kavala e l'epoca della «Questione d'Oriente».", "b1ca7226"]},
"OLAYLAR:1808-10-07:0":{"b": ["Sened-i İttifak", "cce49ef5"], "d": ["Documento firmato tra il palazzo e le potenti famiglie di âyân di provincia sotto la guida di Alemdar Mustafa Paşa, âyân di Rusçuk che aveva portato al trono Mahmud II; mentre gli âyân si impegnavano alla fedeltà al sultano e al sostegno militare, lo Stato riconosceva la loro esistenza e i loro diritti. Essendo il primo esempio nella storia ottomana di limitazione dell'autorità del sultano tramite un documento, è considerato da alcuni storici il lontano inizio della tradizione costituzionale; in pratica perse efficacia nel giro di pochi mesi.", "2d97fdfe"]},
"OLAYLAR:1821-03-06:0":{"b": ["Inizio della rivolta greca", "a7293715"], "d": ["L'insurrezione preparata dall'organizzazione Filikí Etería scoppiò prima in Valacchia e poi, con la sua forza principale, in Morea; lo Stato, impegnato con la questione di Tepedelenli Ali Paşa, tardò a intervenire. Grazie alla forte simpatia greca dell'opinione pubblica europea (filellenismo), la rivolta si trasformò rapidamente in una causa internazionale; così fu accesa la miccia del primo movimento indipendentista riuscito dell'era del nazionalismo nelle terre ottomane. Altri insediamenti perduti nella stessa data: Atina, Balyabadra (Patrasso), İstefe (Tebe), Livadya, Eleusis (Attica), Missolonghi.", "f11097ac"]},
"OLAYLAR:1821-04-02:0":{"b": ["Primo levante armato in Morea", "77e6250f"], "d": ["Dopo il passaggio del Prut la rivolta si estese alla Morea: all'azione armata iniziata a Kalavryta (21 marzo giuliano) seguirono i movimenti di Patrasso, Kalamata e Mani; la Morea si trasformò rapidamente in un'insurrezione generale e l'amministrazione ottomana perse la maggior parte della penisola. Altri insediamenti perduti nella stessa data: Atina, Balyabadra (Patrasso), İstefe (Tebe), Livadya, Eleusis (Attica), Missolonghi.", "143953b8"]},
"OLAYLAR:1826-06-15:0":{"b": ["Vak'a-i Hayriyye — abolito il corpo dei Giannizzeri", "08c9372a"], "d": ["I giannizzeri, che avevano rovesciato le marmitte contro l'addestramento del neocostituito corpo Eşkinci, furono annientati nelle loro caserme dell'Etmeydanı dal fuoco dei cannoni delle truppe fedeli preparate in anticipo da Mahmud II; il corpo fu abolito insieme a tutte le sue sezioni e ai tekke bektashi collegati. Questa operazione, passata alla storia con il nome di «evento fausto», liquidando un'istituzione di quattro secoli aprì la strada all'esercito degli Asâkir-i Mansûre-i Muhammediyye e a tutte le successive riforme di centralizzazione.", "9ee152dd"]},
"OLAYLAR:1827-10-20:0":{"b": ["Incursione di Navarino", "ee579e7f"], "d": ["La flotta ottomano-egiziana, impegnata a reprimere la rivolta greca, fu incendiata a Navarino dalla flotta combinata anglo-franco-russa entrata nel porto senza dichiarazione di guerra; andarono perduti quasi sessanta navi e migliaia di marinai. L'incursione, liquidata dalla diplomazia europea come «evento sfortunato», garantì di fatto l'indipendenza greca e aprì la strada alla guerra ottomano-russa del 1828–29.", "0d4b2c6f"]},
"OLAYLAR:1839-11-03:0":{"b": ["Editto di Tanzimat", "5042ce7b"], "d": ["Con il Hatt-ı Hümâyun letto a Gülhane la sicurezza della vita, dei beni e dell'onore di tutti i sudditi, senza distinzione di religione, fu posta sotto garanzia dello Stato; furono proclamati i princìpi di giustizia nella tassazione, ordine nel servizio militare e nessuna pena senza processo. L'editto, opera di Mustafa Reşid Paşa, è considerato il primo grande documento di carattere costituzionale della modernizzazione ottomana e ha dato il nome all'epoca di riforme del «Periodo del Tanzimat» (1839–1876); in questo quadro furono condotte radicali ristrutturazioni dell'amministrazione, del diritto, dell'istruzione e delle finanze.", "6ace4b82"]},
"OLAYLAR:1853-10-04:0":{"b": ["Inizio della guerra di Crimea", "3b9ca3c8"], "d": ["La crisi iniziata con la questione dei luoghi santi e la pretesa russa di protezione sui sudditi ortodossi si trasformò in conflitto aperto con la dichiarazione di guerra ottomana; dopo l'incursione di Sinope, Inghilterra e Francia (poi il Piemonte) entrarono in guerra dalla parte ottomana. La guerra, vinta con lo sbarco degli eserciti alleati in Crimea e la presa di Sebastopoli e conclusa con la pace di Parigi del 1856; tuttavia il primo debito estero contratto negli anni di guerra (1854) gettò l'impero in una spirale di dipendenza finanziaria destinata a durare mezzo secolo.", "bae16135"]},
"OLAYLAR:1856-02-18:0":{"b": ["Editto di Riforma (Islahat Fermanı)", "78ff234d"], "d": ["L'editto proclamato prima dei negoziati di pace di Parigi, ampliando i princìpi del Tanzimat, riconobbe ai sudditi non musulmani ampi diritti di uguaglianza, inclusi l'impiego pubblico, il servizio militare e l'apertura di scuole; le organizzazioni comunitarie furono riordinate. Con il trattato di Parigi firmato subito dopo lo Stato ottomano fu ufficialmente ammesso alla famiglia del diritto internazionale europeo e la sua integrità territoriale fu posta sotto garanzia comune delle grandi potenze — garanzia che nella pratica sarebbe stata una nuova porta per gli interventi.", "cfe6d847"]},
"OLAYLAR:1876-12-23:0":{"b": ["Kanûn-ı Esâsî — Prima Monarchia Costituzionale", "0fe052c1"], "d": ["Nel giorno dell'apertura della conferenza internazionale riunita a Costantinopoli per discutere la crisi balcanica fu proclamata con colpi di cannone la prima costituzione ottomana; con il Kanûn-ı Esâsî, opera del movimento dei «Giovani Ottomani» guidato da Midhat Paşa, fu istituito un parlamento bicamerale. Il Meclis-i Meb'ûsan fu aperto nel marzo 1877; ma Abdülhamid II, adducendo la guerra del '93, nel febbraio 1878 sospese il parlamento a tempo indeterminato e la costituzione rimase sospesa per trent'anni.", "c0f01a41"]},
"OLAYLAR:1877-04-24:0":{"b": ["Guerra del '93 (guerra russo-ottomana 1877–78)", "5bd96af7"], "d": ["Nella guerra detta «Guerra del '93» perché corrispondente all'anno rûmî 1293, gli eserciti russi attaccarono su due fronti; benché la difesa di Plevna di Gazi Osman Paşa e le battaglie del Caucaso di Ahmed Muhtar Paşa siano diventate epiche, il fronte crollò e i Russi avanzarono fino a Yeşilköy (Santo Stefano). La guerra avviò le grandi ondate di migrazione musulmana dai Balcani e dal Caucaso verso Costantinopoli, i cui effetti giungono fino a oggi; la struttura demografica e finanziaria dell'impero non tornò più com'era.", "3a2b2296"]},
"OLAYLAR:1878-07-13:0":{"b": ["Trattato di Berlino", "47f76a49"], "d": ["Il Congresso di Berlino, che rivide nel nome dell'equilibrio delle grandi potenze la «Grande Bulgaria» creata da Santo Stefano, lasciò comunque un quadro pesante: Serbia, Montenegro e Romania divennero indipendenti; fu istituito il Principato autonomo di Bulgaria; Bosnia-Erzegovina fu lasciata all'occupazione austriaca, Cipro all'amministrazione inglese, Kars-Ardahan-Batum alla Russia. L'ordine ottomano di cinquecento anni in Rumelia si dissolse in gran parte; la «questione d'Oriente» divenne un tema costante della diplomazia europea. Altri insediamenti perduti nella stessa data: Filibe, Vidin, Tırnova, Varna, Şumnu, Silistre, Rusçuk, Bükreş, Yaş, Köstence. La Romania, in cambio della cessione della Bessarabia alla Russia, ottenne Tulça (Tulcea) e la Dobrugia: Tulça, Babadağı (Babadag), Maçin, İshakçı (Isaccea), Hırsova (Hârșova) e Mangalya (Mangalia), nella Dobrugia settentrionale, passarono alla Romania.", "5c7d5594"]},
"OLAYLAR:1881-05-12:0":{"b": ["Occupazione della Tunisia e Düyûn-ı Umûmiyye", "c7e25598"], "d": ["La Francia, col pretesto di incidenti sul confine algerino, occupò la Tunisia e la pose sotto il proprio protettorato con il trattato del Bardo; la presenza ottomana in Nord Africa si ridusse alla Tripolitania. Con il Decreto di Muharrem emanato nello stesso anno fu istituita l'Amministrazione del Debito Pubblico Ottomano (Düyûn-ı Umûmiyye), nella quale erano rappresentati i creditori per la gestione dei debiti esteri in bancarotta: entrate fondamentali come sale, tabacco e seta furono assegnate direttamente a questa amministrazione straniera e la sovranità finanziaria fu gravemente limitata. Altri insediamenti perduti nella stessa data: Kayrevan, Gabes, Sfaks, Cerbe (Djerba).", "64f23b86"]},
"OLAYLAR:1882-09-13:0":{"b": ["Occupazione britannica dell'Egitto", "f1269768"], "d": ["Il movimento di Urâbî Paşa, sorto in Egitto contro la bancarotta finanziaria e il controllo straniero, fu schiacciato dalla vittoria di Tell el-Kebir dell'esercito britannico sbarcato dopo il bombardamento di Alessandria, e il Cairo fu occupato. Sebbene giuridicamente l'Egitto restasse legato agli Ottomani, di fatto passò sotto amministrazione britannica; il controllo del Canale di Suez si collocò al centro della strategia imperiale britannica.", "b7bcf2d2"]},
"OLAYLAR:1908-07-23:0":{"b": ["Proclamazione della Seconda Monarchia Costituzionale", "95ee2fd2"], "d": ["Di fronte al movimento cresciuto con la salita in montagna in Macedonia di ufficiali legati al Comitato Unione e Progresso, Abdülhamid II rimise in vigore il Kanûn-ı Esâsî; la «proclamazione della libertà» fu accolta con entusiasmo e si andò alle elezioni. Ma la stabilità non arrivò: dopo la repressione dell'Incidente del 31 Mart (aprile 1909) Abdülhamid fu deposto; in quei mesi convulsi si ebbero anche l'indipendenza della Bulgaria, l'annessione della Bosnia e l'orientamento di Creta verso la Grecia.", "370f359f"]},
"OLAYLAR:1911-09-29:0":{"b": ["Guerra di Tripolitania", "ed441994"], "d": ["L'Italia, in cerca di colonie, dichiarò guerra alla Tripolitania, ultimo territorio ottomano in Nord Africa, e ne occupò le coste; poiché lo Stato, privo di flotta, non poteva inviare un esercito regolare, giovani ufficiali come Mustafa Kemal ed Enver Bey passarono segretamente nella regione e organizzarono con le tribù senussite una resistenza efficace. Con il trattato di Ouchy (18 ottobre 1912), firmato per lo scoppio della guerra balcanica, la Libia fu lasciata all'Italia; l'Italia occupò inoltre Rodi e il Dodecaneso.", "9820482a"]},
"OLAYLAR:1913-05-30:0":{"b": ["Trattato di Londra — la perdita della Rumelia", "f3f976df"], "d": ["Con il trattato di Londra, che pose fine alla Prima guerra balcanica, furono perduti tutti i territori a ovest della linea Midye-Enez e le isole dell'Egeo; l'Albania divenne indipendente. Della Rumelia, per oltre cinquecento anni baricentro demografico, economico e culturale dell'impero, sarebbe rimasta solo la Tracia orientale (Edirne fu ripresa nella Seconda guerra balcanica); la perdita irrigidì radicalmente la politica di guerra e di insediamento dell'amministrazione unionista. Andarono perduti questi luoghi a ovest della linea Midye-Enez: Üsküp, Köprülü (Veles), İştip (Štip), Ustrumca, Doyran, Gevgili (Gevgelija), Manastır, Ohri, Debre (Dibra), Prizren, Priştine, Peç (Pejë), Yenipazar (Novi Pazar), Kosova Ovası (Kosovo Polje); Serez, Drama, Kavala, Petriç, Nevrokop, İskeçe, Gümülcine, Dedeağaç, Dimetoka, Çirmen, Ferecik (Feres), Sofulu (Soufli), Orestiada (Kumçiftliği), Praviște (Eleftheroupoli), Stérna, Távri, Umur Fakih (Fakia), Malak Dervent (Lalkovo); a Creta Hanya, Kandiye, Girit (Resmo), Sitiye (Sitia) e İsfakiye (Sfakia).", "b193bdae"]},
"OLAYLAR:1914-11-01:0":{"b": ["Ingresso nella Prima guerra mondiale", "05a0252e"], "d": ["L'ammissione attraverso lo Stretto, come se fossero state acquistate, delle corazzate Goeben e Breslau sfuggite agli Inglesi trascinò lo Stato passo dopo passo accanto alla Germania; con il bombardamento dei porti russi da parte della flotta al comando dell'ammiraglio Souchon (29 ottobre) la guerra iniziò di fatto e le dichiarazioni reciproche giunsero all'inizio di novembre. Nonostante la proclamazione del Cihâd-ı Ekber, l'effetto atteso non si produsse; per quattro anni l'impero si trovò in una guerra per l'esistenza su cinque diversi fronti, dal Caucaso alla Palestina.", "a9f179e7"]},
"OLAYLAR:1915-03-18:0":{"b": ["Vittoria di Çanakkale", "95d888e8"], "d": ["L'armata alleata, che mirava a prendere Costantinopoli e a raggiungere la Russia, il 18 marzo fu respinta dallo Stretto dal fuoco dei campi minati e delle batterie; lo sbarramento posato dalla nave posamine Nusret decise le sorti della battaglia. Anche l'operazione terrestre di Gallipoli, iniziata in aprile, fu fermata ad Anafartalar e a Conkbayırı; gli alleati evacuarono completamente la penisola nel gennaio 1916. Il nome del tenente colonnello Mustafa Kemal si fece conoscere su questo fronte; la vittoria, ottenuta con circa un quarto di milione tra caduti e perdite, è considerata il luogo in cui nacquero i quadri e lo spirito della Guerra di Liberazione Nazionale.", "005303c3"]},
"OLAYLAR:1916-06-10:0":{"b": ["Rivolta dello sceriffo Hussein", "75f7c58c"], "d": ["L'emiro della Mecca, lo sceriffo Hussein, dopo una corrispondenza segreta con gli Inglesi si sollevò con la promessa di un regno arabo indipendente; la ferrovia del Hegiaz divenne bersaglio di incursioni. Benché la leggendaria difesa di Medina da parte di Fahreddin Paşa, protrattasi fino a dopo l'armistizio, sia rimasta come simbolo di resistenza, la rivolta, unendosi all'avanzata britannica sul fronte della Palestina, accelerò la dissoluzione del dominio ottomano nelle province arabe. Altri insediamenti perduti nella stessa data: Tâif.", "a0e859bd"]},
"OLAYLAR:1918-10-30:0":{"b": ["Armistizio di Mudros", "9e87c767"], "d": ["Lo Stato ottomano, i cui fronti erano stati separati dal crollo della Bulgaria, uscì dalla guerra con l'armistizio firmato sulla corazzata Agamemnon. L'apertura degli Stretti e in particolare l'articolo 7, che consentiva l'occupazione dei luoghi la cui sicurezza fosse minacciata, divennero in breve il paravento giuridico di una spartizione di fatto: furono occupate Mosul, Alessandretta, poi Smirne e Costantinopoli. L'armistizio è considerato il documento della fine effettiva dell'impero. Altri insediamenti perduti nella stessa data: Hama, Şam, Humus.", "261b57f2"]},
"OLAYLAR:1919-05-19:0":{"b": ["Mustafa Kemal a Samsun — la Guerra di Liberazione Nazionale", "09a8f784"], "d": ["Nel clima di indignazione creato dall'occupazione di Smirne, Mustafa Kemal Paşa, sbarcato a Samsun come ispettore della 9ª Armata, volse il suo incarico ufficiale all'organizzazione della resistenza in Anatolia. La Circolare di Amasya e i congressi di Erzurum e Sivas ne sono la prosecuzione; il principio «l'indipendenza della nazione sarà salvata ancora dalla determinazione e dalla decisione della nazione» divenne il nucleo del programma politico della Guerra di Liberazione.", "330e4c51"]},
"OLAYLAR:1920-04-23:0":{"b": ["Apertura della Grande Assemblea Nazionale e Sèvres", "2008feec"], "d": ["Per l'occupazione ufficiale di Costantinopoli e lo scioglimento del Meclis-i Meb'ûsan, il 23 aprile 1920 fu aperta ad Ankara la Grande Assemblea Nazionale; l'assemblea, che concentrò in sé poteri straordinari, divenne il nucleo del nuovo Stato basato sulla volontà nazionale. Il trattato di Sèvres, firmato in agosto dal governo di Costantinopoli, spartiva l'Anatolia; la Grande Assemblea dichiarò traditori della patria i firmatari e Sèvres non poté mai essere applicato.", "9b4f7c0b"]},
"OLAYLAR:1921-09-13:0":{"b": ["Battaglia del Sakarya", "f2f970a6"], "d": ["L'offensiva greca, giunta fino a 50 chilometri da Ankara, fu spezzata in una battaglia di 22 giorni e 22 notti condotta da Mustafa Kemal Paşa, che aveva assunto il comando supremo, con l'ordine «non esiste linea di difesa, esiste superficie di difesa». L'esercito greco passò per la prima volta alla difesa strategica; la vittoria portò a Mustafa Kemal i titoli di gazi e di müşir (maresciallo) e aprì la porta all'Accordo di Ankara con la Francia e al riconoscimento internazionale.", "f3372310"]},
"OLAYLAR:1922-09-09:0":{"b": ["Grande Offensiva e liberazione di Smirne", "172a50c4"], "d": ["L'offensiva lanciata da Kocatepe la mattina del 26 agosto raggiunse il 30 agosto, a Dumlupınar, l'annientamento delle forze principali greche con la Battaglia del Comandante in Capo; con l'inseguimento condotto sotto l'ordine «Armate, il vostro primo obiettivo è il Mediterraneo, avanti!», il 9 settembre Smirne fu liberata. Con l'armistizio di Mudanya (11 ottobre) la Tracia orientale fu ripresa senza combattere; la vittoria militare determinò la forza al tavolo del nuovo Stato che sarebbe stato costituito a Losanna.", "02bd94a5"]},
"OLAYLAR:1922-11-01:0":{"b": ["Abolizione del sultanato", "9f36a9f6"], "d": ["Poiché alle trattative di Losanna fu invitato anche il governo di Costantinopoli, il 1° novembre 1922 la Grande Assemblea Nazionale separò sultanato e califfato e abolì il sultanato; il dominio dinastico ottomano di 623 anni terminò giuridicamente. Mehmed VI Vahideddin il 17 novembre lasciò il paese su una corazzata inglese; alla carica di califfo fu chiamato con decisione dell'Assemblea Abdülmecid Efendi e anche questa carica sarebbe stata abolita il 3 marzo 1924.", "910b763d"]},
"OLAYLAR:1923-07-24:0":{"b": ["Trattato di Losanna", "38c27f7d"], "d": ["Con il Trattato di pace di Losanna, firmato al termine di otto mesi di aspri negoziati, furono riconosciuti sul piano internazionale i confini, la piena indipendenza e la sovranità del nuovo Stato turco; le capitolazioni furono abolite, il Düyûn-ı Umûmiyye fu avviato alla liquidazione e fu regolato lo scambio di popolazioni. Losanna, che rese di fatto nullo Sèvres, è considerata la vittoria diplomatica della Guerra di Liberazione e il documento estero fondativo della Repubblica.", "6d498c3f"]},
"OLAYLAR:1923-10-29:0":{"b": ["Proclamazione della Repubblica", "d5bfcdfb"], "d": ["Con l'accettazione da parte della Grande Assemblea Nazionale, tramite modifica costituzionale, della disposizione «la forma di governo dello Stato turco è la repubblica», fu proclamata la Repubblica; Mustafa Kemal Paşa fu eletto primo presidente. Così si chiudeva l'avventura ottomana di 624 anni iniziata nel 1299 come beylik di frontiera; il nuovo Stato, in cui la sovranità appartiene incondizionatamente alla nazione, fu fondato sull'eredità dell'impero.", "f5cabb8c"]},
"OLAYLAR_EK:1300-01-01:0":{"b": ["Presa di Köprühisar e preparativi per la fondazione di Yenişehir", "39abff03"], "d": ["Con la caduta delle fortezze di passo tra Bursa e İznik fu posta la base del quartier generale avanzato che avrebbe stretto d'assedio le due città.", "72fa9808"]},
"OLAYLAR_EK:1301-01-01:0":{"b": ["Fondazione di Yenişehir", "d3275837"], "d": ["Per dirigere gli assedi di Bursa e İznik fu fondato il primo insediamento-guarnigione ottomano regolare; Orhan Gazi nacque qui.", "39c98a4b"]},
"OLAYLAR_EK:1302-08-01:0":{"b": ["Primo assedio di İznik e conquista di Marmaracık", "cdca2349"], "d": ["İznik fu assediata per la prima volta ma non cadde (la conquista definitiva è del 1331); nel frattempo fu presa la vicina fortezza di Marmaracık.", "31c4c65f"]},
"OLAYLAR_EK:1313-01-01:0":{"b": ["Köse Mihal si converte all'Islam e passa agli Ottomani", "ca0d86e1"], "d": ["Köse Mihal, tekfur di Harmankaya, si convertì all'Islam e si unì a Osman Gazi con la sua fortezza e i suoi uomini; fu il primo comandante ottomano di origine bizantina.", "327b4cdc"]},
"OLAYLAR_EK:1320-01-01:0":{"b": ["Orhan Bey assume di fatto il governo", "6dadbefc"], "d": ["Per la vecchiaia e la malattia di Osman Gazi, la direzione e la conduzione effettiva dell'assedio di Bursa e delle campagne passarono al figlio Orhan Bey (l'ascesa ufficiale al trono è del 1326).", "280c6e0d"]},
"OLAYLAR_EK:1324-01-01:0":{"b": ["Conquista di Akyazı e dell'isola di İmralı", "d041b0c8"], "d": ["Fu presa Akyazı, a nord del Sakarya; con la conquista dell'isola di İmralı gli Ottomani, per la prima volta, divennero vicini dell'isola di Marmara.", "591424a4"]},
"OLAYLAR_EK:1324-03-01:0":{"b": ["Conquista di Gemlik (Kios) e Armutlu", "682d3bac"], "d": ["Tagliato l'ultimo collegamento marittimo di Bursa, la città fu preparata alla resa del 1326.", "c2b80b4a"]},
"OLAYLAR_EK:1326-01-01:0":{"b": ["Akça Koca conquistò Kandıra e dintorni", "341bb97e"], "d": ["Akça Koca, uno dei beg di frontiera di Orhan Gazi, mentre compiva incursioni nella regione di İzmit dal suo quartier generale a ovest del lago di Sapanca, verso il 1326 si impadronì di Kandıra e dei dintorni. İzmit era ancora in mano bizantina; la città sarebbe caduta solo nel 1337.", "ed042ad1"]},
"OLAYLAR_EK:1326-01-01:1":{"b": ["Annessione di Yalova e Karamürsel", "133cb07a"], "d": ["Yalova e dintorni, sulla costa meridionale del golfo di İzmit, quest'anno passarono in mano turca; la fascia costiera fu data come timar da Orhan Bey a Karamürsel Gazi.", "592a86bc"]},
"OLAYLAR_EK:1328-01-01:0":{"b": ["Akça Koca prese Aydos e la fortezza di Samandıra", "ce4daa8a"], "d": ["Dopo la presa di Kandıra, Akça Koca insieme a Konuralp e Gazi Abdurrahman prese la fortezza di Aydos presso Kartal e poi la fortezza di Samandıra a nord di essa; la regione di Samandıra gli fu data come proprietà. Akça Koca morì nel 1328 presso Kandıra; il beylik di frontiera fu dato al principe Murad.", "f2ef1bde"]},
"OLAYLAR_EK:1330-01-01:0":{"b": ["Alleanza ottomano-Aydın-Saruhan", "9df6bb74"], "d": ["Tre beylik agirono insieme contro Bisanzio; la flotta di Umur Bey degli Aydınoğlu logorò Bisanzio su un secondo fronte con le incursioni sulle coste della Tracia.", "32ca49ea"]},
"OLAYLAR_EK:1354-08-01:0":{"b": ["Presa di Ankara", "49bf1f6d"], "d": ["Ankara, retta dagli ahi, entrò nell'amministrazione ottomana; si aprì la strada dell'Anatolia centrale. Altri luoghi annessi nella stessa data: Sivrihisar, Çankırı.", "eec5d13e"]},
"OLAYLAR_EK:1360-01-01:0":{"b": ["Tagliate le vie di soccorso di Edirne: fortezze di Çorlu, Lüleburgaz, Babaeski e Keşan", "8e8ad485"], "d": ["Il principe Murad, ripresa la campagna di conquista dopo la liberazione di Halil, mandò gli akıncı fino alle porte di Costantinopoli per isolare Edirne da ogni aiuto esterno. Furono presi le fortezze di Çorlu, Lüleburgaz e Babaeski sulla strada Costantinopoli-Edirne e Keşan, snodo stradale della Tracia meridionale. La resa di Edirne giunse dopo il completamento di questo anello d'assedio.", "fb171002"]},
"OLAYLAR_EK:1371-09-26:0":{"b": ["Battaglia di Çirmen — controllo della valle della Maritza", "cd738d8d"], "d": ["L'esercito dei signori serbi fu disperso in un attacco notturno; i signori locali serbi/bulgari della Macedonia e dei Rodopi cominciarono uno per uno a pagare tributo agli Ottomani — non una conquista diretta, ma l'inizio di un'ondata di vassallaggio. Nella tradizione ottomana questa battaglia è narrata anche con il nome di «Sırpsındığı» e con la data del 1364, come attacco notturno di Hacı İlbey contro l'esercito crociato venuto a riprendere Edirne; il TDV afferma che tale data è errata e che le due narrazioni si riferiscono alla stessa battaglia.", "7b2779cd"]},
"OLAYLAR_EK:1372-06-01:0":{"b": ["Conquista di Filibe e Eski Zağra", "e780c9ae"], "d": ["Furono prese Filibe (Plovdiv), a monte della valle della Maritza, e Eski Zağra (Stara Zagora) a nord; lo zarato bulgaro fu reso tributario. Il percorso Tatarpazarcığı-İhtiman tra Filibe e Sofia rimase in mano ai signori locali divenuti vassalli dopo Çirmen.", "b8131db8"]},
"OLAYLAR_EK:1381-01-01:0":{"b": ["Dote germiyanide: annessione di Kütahya", "d6a6fe61"], "d": ["Nel matrimonio di Devletşah Hatun, figlia di Germiyanoğlu Süleyman Şah, con Yıldırım Bayezid, Kütahya, Simav, Tavşanlı ed Eğrigöz passarono agli Ottomani come dote — l'esempio classico di espansione senza guerra. Altri luoghi annessi nella stessa data: Afyon.", "3321bbba"]},
"OLAYLAR_EK:1381-06-01:0":{"b": ["Acquisto del territorio di Hamîd: annessione di Isparta", "4a1b6047"], "d": ["Hamîdoğlu Hüseyin Bey vendette a Murad I, in cambio di denaro, una parte del suo beylik (Akşehir-Beyşehir-Isparta); il resto del territorio di Hamid sarebbe stato annesso da Yıldırım nel 1391.", "d316dea5"]},
"OLAYLAR_EK:1383-09-19:0":{"b": ["Conquista di Serez", "d4d28b60"], "d": ["Fu presa Serez, chiave della Macedonia orientale; Salonicco entrò nel cerchio d'assedio. La linea Köstendil-Petriç-Nevrokop-Drama tra Sofia e Serez a questa data non era ancora annessa direttamente: passò in successione a vassallaggio fra gli anni 1370 e il 1383 e a governo diretto dopo il 1383.", "573cc19c"]},
"OLAYLAR_EK:1385-09-01:0":{"b": ["Conquista di Sofia", "96d5f01f"], "d": ["Furono messi sotto controllo i passi occidentali dei monti Balcani; poiché a questa data Serez era già in mano dal 1383, i territori di Tracia e Macedonia formavano un blocco ininterrotto.", "f358b568"]},
"OLAYLAR_EK:1386-01-01:0":{"b": ["Conquista di Niš", "77f5d632"], "d": ["Con la presa di Niš, chiave della valle della Morava, il despotato serbo fu direttamente minacciato.", "15f52aaf"]},
"OLAYLAR_EK:1387-04-09:0":{"b": ["Prima resa di Salonicco", "96010ee9"], "d": ["Dopo un lungo blocco la città si arrese (sarebbe stata restituita a Bisanzio nel 1403 e conquistata definitivamente nel 1430). Altri luoghi annessi nella stessa data: Kavala.", "5ef8bffd"]},
"OLAYLAR_EK:1387-06-08:0":{"b": ["Ahidnâme ottomano-genovese — rinnovo del trattato del 1352", "be11d17a"], "d": ["Con gli ambasciatori genovesi di Pera fu rinnovato l'accordo commerciale del 1352, risalente all'epoca di Orhan Gazi; furono nuovamente fissati le imposte, il trattamento dei prigionieri e il libero commercio tra i due Stati. È considerato il primo ahidnâme ufficialmente noto di amicizia e commercio tra Ottomani e Genovesi — non un'alleanza militare, ma un accordo interamente commerciale.", "46b0f65b"]},
"OLAYLAR_EK:1388-01-01:0":{"b": ["Campagna di Bulgaria di Çandarlı Ali Paşa: presa di Şumnu e Rusçuk", "2781c3a9"], "d": ["Le fortezze dello zarato bulgaro lungo il Danubio furono prese in una sola campagna; non va confuso con la sconfitta subita nello stesso anno a Bileća in Bosnia — fu un successo simultaneo su un fronte separato. Tırnova e Vidin erano ancora gli ultimi centri bulgari in mano.", "d6eaf4cd"]},
"OLAYLAR_EK:1390-01-01:0":{"b": ["Annessione dei beylik dell'Anatolia occidentale: Saruhan, Aydın, Menteşe", "dcc33b71"], "d": ["Tre beylik furono annessi in un'unica volta: Manisa, centro dei Saruhanoğulları; Aydın, centro degli Aydınoğulları (compresa la fortezza superiore di Smirne, ma con porto/fortezza bassa ancora ai Cavalieri di San Giovanni — fino al 1402); Muğla-Milas, centro dei Menteşeoğulları, compresa la fascia costiera Datça-Bodrum-Marmaris-Fethiye. Le coste egee furono per la prima volta riunite sotto un'unica mano. Altri luoghi annessi nella stessa data: Söke.", "7f3094f2"]},
"OLAYLAR_EK:1392-01-01:0":{"b": ["Annessione del territorio di Teke: annessione di Antalya", "fdbeee5c"], "d": ["Il territorio di Teke, sulla costa mediterranea, fu annesso ai territori ottomani. I Tekeoğulları sono un ramo staccatosi dagli Hamîdoğulları: Feleküddin Dündar Bey aveva lasciato Antalya, da lui conquistata, al fratello Yûnus Bey e verso il 1321 era nato un beylik separato. Per questo Antalya e dintorni sulla mappa dopo il 1321 sono mostrati con il colore dei Tekeoğulları e non degli Hamîdoğulları. Il beylik fu ricostituito dopo la battaglia di Ankara e fu liquidato in modo definitivo solo nel 1423.", "09a83d97"]},
"OLAYLAR_EK:1392-01-06:0":{"b": ["Conquista di Üsküp", "9e5a1af5"], "d": ["Fu presa Üsküp, centro della Macedonia del Vardar; Üsküp divenne uno dei principali centri di frontiera della Rumelia.", "8722b1dd"]},
"OLAYLAR_EK:1392-11-01:0":{"b": ["Annessione di Kastamonu", "876330ba"], "d": ["Il ramo di Kastamonu dei Candaroğulları fu liquidato; il ramo di Sinope continuò come vassallo. Altri luoghi annessi nella stessa data: Bartın, Safranbolu.", "34d8e600"]},
"OLAYLAR_EK:1393-06-17:0":{"b": ["Caduta di Tırnova — annessione della Bulgaria", "ff666977"], "d": ["Cadde la capitale dello zarato bulgaro; la Bulgaria entrò sotto governo ottomano diretto. Altri luoghi annessi nella stessa data: Plevne, Lofça.", "182028e2"]},
"OLAYLAR_EK:1393-06-17:1":{"b": ["La fortezza di Lofça (Lovech) passa agli Ottomani", "a55e87a0"], "d": ["Lofça, una delle fortezze dello zar bulgaro Ivan Šišman, nella campagna del 1393 in cui cadde Tırnova fu annessa ai territori ottomani insieme alle altre province di Šišman. La fonte non è categorica: si «ritiene» che la conquista sia avvenuta in quest'anno.", "9430a123"]},
"OLAYLAR_EK:1393-09-01:0":{"b": ["Annessione della Dobrugia", "478e36f2"], "d": ["Furono annessi i territori della Dobrugia che si estendono fino al delta del Danubio. Altri luoghi annessi nella stessa data: Silistre, Köstence.", "05bdabb4"]},
"OLAYLAR_EK:1394-01-01:0":{"b": ["Discesa in Tessaglia", "8bec60dd"], "d": ["La pianura della Tessaglia, centrata su Yenişehir (Larissa), fu posta sotto amministrazione ottomana. Altri luoghi annessi nella stessa data: Tırhala, İzdin (Lamia).", "d9f2128c"]},
"OLAYLAR_EK:1395-01-01:0":{"b": ["Conquista di Nicopoli", "b9791717"], "d": ["Dopo la battaglia di Rovine del 1395 contro i Valacchi, Yıldırım Bayezid prese la fortezza di Nicopoli sul Danubio; alcune cronache bulgare anonime indicano che la conquista avvenne il 3 giugno 1395. La data della conquista non è univoca nelle fonti: la voce Niğbolu Savaşı del TDV İslâm Ansiklopedisi scrive che Bayezid prese Silistra e Nicopoli in una campagna sul Danubio del 1394. La fortezza sarebbe stata assediata nella celebre Crociata del 1396, ma non sarebbe caduta. Altri luoghi annessi nella stessa data: Ohri.", "bc450a9f"]},
"OLAYLAR_EK:1396-10-01:0":{"b": ["Annessione di Vidin", "ee1ae44b"], "d": ["Dopo la vittoria di Nicopoli fu annesso anche Vidin, ultimo principato bulgaro.", "28f4258d"]},
"OLAYLAR_EK:1397-07-01:0":{"b": ["Prima annessione di Karaman", "3cf07876"], "d": ["Con la vittoria di Akçay i territori dei Karamanoğulları furono annessi per la prima volta agli Ottomani (sarebbero stati ricostituiti durante il Fetret).", "788bdca3"]},
"OLAYLAR_EK:1398-07-01:0":{"b": ["Annessione delle coste del Canik: Samsun", "af9c40fa"], "d": ["Nel vuoto creato dalla cattura di Kadı Burhâneddin da parte dell'aqquyunlu Karayülük Osman Bey, Yıldırım Bayezid pose dapprima sotto amministrazione ottomana la regione del Canik, sulla costa del Mar Nero. Samsun e dintorni divennero così il primo porto del Mar Nero della dinastia. La linea interna Sivas-Tokat-Kayseri sarebbe stata annessa due settimane dopo, con la dissoluzione di fatto dello Stato di Kadı Burhâneddin.", "4b2f9a80"]},
"OLAYLAR_EK:1399-09-01:0":{"b": ["Presa di Malatya", "7cb6ae16"], "d": ["Fu conquistata Malatya, sul confine mamelucco — uno dei passi che accrebbero la tensione con Tamerlano.", "3b7ba002"]},
"OLAYLAR_EK:1400-01-01:0":{"b": ["Tamerlano prese Malatya e la lasciò a Karayülük Osman — quando Tamerlano si ritirò i Dulkadiroğulları la ripresero", "ad2ce7d8"], "d": ["Yıldırım Bayezid, lasciata Malatya, presa nel 1399, a Dulkadıroğlu Nasreddin Mehmed, era tornato a Bursa. Tamerlano, entrato in Anatolia nel 1400, prese prima Sivas ed Elbistan, poi Malatya; la città e i dintorni furono saccheggiati e l'amministrazione fu lasciata a Karayülük Osman, che era con Tamerlano. Quando Tamerlano lasciò la regione, Malatya fu di nuovo dominata dai Dulkadiroğulları; il dominio ottomano terminò dunque prima di Ankara.", "5889cce9"]},
"OLAYLAR_EK:1425-06-01:0":{"b": ["Nuova annessione dei beylik dell'Anatolia occidentale: Menteşe e Aydın", "aca30a48"], "d": ["I due beylik egei ricostituiti durante il Fetret Devri furono definitivamente annessi ai territori ottomani sotto Murad II. Secondo la voce Menteşeoğulları del TDV, Murad II conquistò il territorio di Menteşe nell'827 (1424) e fece imprigionare i due fratelli a capo del beylik. Secondo la voce Aydınoğulları, il beylerbey d'Anatolia Hamza Bey fece catturare Cüneyd Bey, di nuovo uscito dall'obbedienza, e lo fece giustiziare con la sua famiglia (829/1425-26), e il territorio di Aydın passò agli Ottomani. I Cavalieri di San Giovanni, che dal 1344 tenevano la fortezza portuale di Smirne, l'avevano perduta nel 1402 a favore di Tamerlano e la regione era tornata sotto il controllo degli Aydınoğulları; con questa annessione anch'essa fu annessa agli Ottomani. Il territorio di Teke (Antalya) non è oggetto di questa voce: i Tekeoğulları erano stati liquidati separatamente nel 1423. Germiyan sarebbe invece stato annesso nel 1429 per testamento.", "92fa8d97"]},
"OLAYLAR_EK:1430-03-29:0":{"b": ["Conquista definitiva di Salonicco", "bc021768"], "d": ["La città, sotto dominio veneziano, fu presa d'assalto; il secondo grande porto della Rumelia divenne definitivamente ottomano. Altri luoghi annessi nella stessa data: Kesendire (Cassandra).", "8853e257"]},
"OLAYLAR_EK:1430-10-09:0":{"b": ["Resa di Ioannina", "ee45cb52"], "d": ["Ioannina, centro dell'Epiro, si arrese con un accordo.", "1aad46c0"]},
"OLAYLAR_EK:1456-06-04:0":{"b": ["Conquista di Atene", "4f0f1bb2"], "d": ["Il Ducato di Atene finì; sull'Acropoli fu issata la bandiera ottomana. Altri luoghi annessi nella stessa data: İstefe (Tebe), Livadya.", "a912625d"]},
"OLAYLAR_EK:1459-06-20:0":{"b": ["Annessione della Serbia (caduta di Smederevo)", "75fd0a62"], "d": ["Smederevo, capitale del despotato serbo, si arrese; la Serbia divenne un sancak ottomano.", "29bd2888"]},
"OLAYLAR_EK:1460-05-29:0":{"b": ["Conquista della Morea", "7d5a3c18"], "d": ["Il despotato di Morea fu liquidato; la penisola (escluse le fortezze veneziane) entrò sotto amministrazione ottomana.", "14aba74c"]},
"OLAYLAR_EK:1461-06-01:0":{"b": ["Annessione di Sinope", "e03c2739"], "d": ["Il candaroğlu consegnò Sinope senza combattere; si aprì la strada della campagna di Trebisonda. Altri luoghi annessi nella stessa data: Kastamonu, Bartın, Safranbolu. La voce Candaroğulları del TDV cita anche Bolu, Eflani e Tosya tra i territori del beylik dei Candaroğlu annessi nel 1461; nell'atlante anche questi tre luoghi sono registrati in questo giorno come passati dai Candaroğlu agli Ottomani.", "4ef62060"]},
"OLAYLAR_EK:1463-06-01:0":{"b": ["Caduta del Regno di Bosnia — campagna di Bosnia del Conquistatore", "5362e3f2"], "d": ["Quando l'ultimo re di Bosnia, Stjepan Tomašević (1461-1463), confidando nel sostegno occidentale, rifiutò di pagare il tributo, fu considerato decaduto dalla condizione di sovrano soggetto e l'esercito sotto Mehmed il Conquistatore liquidò il Regno di Bosnia in una sola campagna. Il re fu catturato e giustiziato, il regno scomparve e nella regione fu istituito il sancak di Bosnia. Tuttavia la caduta del regno non è la stessa cosa della conquista della Bosnia. L'amministrazione ottomana era già presente nella pianura da quindici anni — Hodidjed e la piana di Saray erano state prese nel 1448 e il beylik di frontiera di Îsâ Bey era stato fondato in mezzo al regno. La conquista non finì neppure nel 1463: Foça nel 1465, Livno nel 1469, il Ducato di Erzegovina nel 1483, il banato di Srebrenik nel 1512, Yayça e Banaluka a nord solo nel 1528, dopo Mohács — gli Ungheresi, dopo il 1463, avevano costituito nel nord della Bosnia un banato che resistette sessantacinque anni. Il luogo che cambia direttamente mano a questa data è Travnik; Yayça passa invece in questa data non agli Ottomani ma all'Ungheria.", "5ac16344"]},
"OLAYLAR_EK:1468-01-01:0":{"b": ["Annessione definitiva di Karaman", "f1dcecaa"], "d": ["I territori centrali dei Karamanoğulları furono annessi in modo definitivo; le lotte interne durarono fino agli anni 1470. Altri luoghi annessi nella stessa data: Niğde, Mostar, Beyşehir.", "da6cfd4c"]},
"OLAYLAR_EK:1470-07-12:0":{"b": ["Conquista di Negroponte", "5c97daf3"], "d": ["Cadde Negroponte, principale base veneziana nell'Egeo.", "189cc474"]},
"OLAYLAR_EK:1471-01-01:0":{"b": ["Annessione di Alanya, Anamur e Silifke (İçel)", "a0b9d461"], "d": ["La fascia costiera dell'İçel, dipendente dai Karamanoğulları (l'intero Mediterraneo tra Antalya e Mersin), fu annessa con la campagna navale di Gedik Ahmed Paşa; Alanya era importante per il suo arsenale strategico di epoca selgiuchide.", "8302df58"]},
"OLAYLAR_EK:1479-01-25:0":{"b": ["Trattato di Costantinopoli — Albania e Scutari", "b09652f7"], "d": ["La guerra ottomano-veneziana di 16 anni terminò; Scutari e le coste albanesi rimasero agli Ottomani. Altri luoghi annessi nella stessa data: Limni, Sisam, Bozbaba (Ay Strati).", "bc2aebf2"]},
"OLAYLAR_EK:1480-08-11:0":{"b": ["Sbarco a Otranto", "7916b89d"], "d": ["Le forze ottomane sbarcate sulla costa della Puglia (Apulia) assediarono e presero la fortezza di Otranto; poiché si entrò in città combattendo, una parte dei notabili che avevano resistito fu giustiziata e un'altra parte presa prigioniera. La tradizione ecclesiastica ricorda i morti come i «martiri di Otranto», circa 800 persone; il TDV attribuisce l'esagerazione di questo numero alla propaganda ecclesiastica. Furono tenute solo la fortezza all'estremità della penisola salentina e il suo ristretto circondario; gli altri territori del Regno di Napoli sulla linea Taranto-Brindisi-Lecce non andarono perduti — questa testa di ponte aperta sull'Italia sarebbe durata un anno.", "0e1004b8"]},
"OLAYLAR_EK:1481-09-10:0":{"b": ["Evacuazione di Otranto", "37371bb0"], "d": ["Alla morte di Mehmed il Conquistatore (3 maggio 1481), senza più speranza di nuovi rinforzi, la guarnigione di Otranto, di fronte all'assedio dell'erede al trono di Napoli Alfonso, evacuò la fortezza per accordo; l'unica testa di ponte ottomana in Italia andò così perduta un anno dopo.", "961ef9c3"]},
"OLAYLAR_EK:1500-08-09:0":{"b": ["Conquista di Modone e Corone", "38b608c4"], "d": ["Furono prese Modone e Corone, i «due occhi» di Venezia in Morea.", "a11c09d0"]},
"OLAYLAR_EK:1501-08-17:0":{"b": ["Conquista di Durazzo", "1f231b98"], "d": ["Durante la guerra ottomano-veneziana del 1499-1503, le forze al comando di Mehmed Bey presero Durazzo, l'ultimo grande porto albanese di Venezia sull'Adriatico. Dopo Scutari (1479) e Valona (1417), con questa conquista la fascia costiera albanese passò interamente sotto il controllo ottomano.", "ad635bca"]},
"OLAYLAR_EK:1515-09-15:0":{"b": ["Annessione dell'Anatolia orientale", "e0cb8f8f"], "d": ["Dopo Çaldıran furono annessi Diyarbakır e dintorni; i beylik curdi furono legati agli Ottomani per opera di İdrîs-i Bitlisî.", "025d3ddc"]},
"OLAYLAR_EK:1526-07-27:0":{"b": ["Conquista della fortezza di Varadino (Petrovaradin)", "abf392a5"], "d": ["L'esercito partito per la campagna di Mohács passò da Belgrado nelle terre ungheresi; di Varadino furono prese prima le periferie e, dopo un assedio di quattordici giorni, cadde anche la fortezza. Solimano ordinò di non bruciare i villaggi lungo la strada, perché ormai erano considerati terra ottomana.", "60a4ae4e"]},
"OLAYLAR_EK:1526-09-01:0":{"b": ["Resa di Buda dopo Mohács — due re sul trono ungherese", "9d3568a0"], "d": ["All'esercito ottomano che marciava su Buda dopo la vittoria di Mohács le chiavi della città furono presentate al sultano l'11 settembre 1526; ma Solimano non tenne Buda e ritirò l'esercito. Nell'Ungheria rimasta senza re i nobili elessero due re distinti: János Szapolyai il 10 novembre 1526 e il 17 dicembre 1526 l'asburgico Ferdinando I. Ferdinando prese Buda nell'agosto 1527. L'insediamento di Szapolyai a Buda come re sotto protezione ottomana avverrà con la campagna del 1529 (si veda la voce del 1529); il governo ottomano diretto sarebbe stato stabilito nel 1541.", "d68817d3"]},
"OLAYLAR_EK:1526-11-10:0":{"b": ["János Szapolyai eletto re d'Ungheria — gli Ottomani riconobbero il suo regno a condizione che fosse vassallo", "32bc6baf"], "d": ["Per il trono ungherese rimasto vacante con la morte del re a Mohács una parte dei nobili elesse János Szapolyai, voivoda di Transilvania; Szapolyai fu incoronato a Székesfehérvár. Gli Ottomani, che avevano lasciato Buda, per tenere la regione come zona cuscinetto riconobbero il regno di Szapolyai a condizione che fosse loro vassallo. Sulla mappa i luoghi legati a Szapolyai appaiono da questa data come vassalli degli Ottomani.", "1d697cbd"]},
"OLAYLAR_EK:1526-12-17:0":{"b": ["Ferdinando I proclamato re d'Ungheria — l'Ungheria occidentale e settentrionale alla corona asburgica", "b3910a2f"], "d": ["L'arciduca asburgico Ferdinando, in base al matrimonio della sorella con Luigi II, avanzò pretese sul trono ungherese e fu proclamato re da una parte dei nobili. L'Ungheria fu così divisa tra due re; la parte occidentale e settentrionale riconobbe Ferdinando. I nobili croati lo elessero a parte all'inizio del 1527.", "1484af4c"]},
"OLAYLAR_EK:1530-01-01:0":{"b": ["Contesa dei due re: Esztergom sotto protezione asburgica, Szeged a Szapolyai", "da92dee5"], "d": ["Esztergom, che dal 1526 passava di mano tra i due re, dopo che l'arcivescovo si trasferì a nord con l'archivio e il tesoro, entrò sotto la protezione asburgica. Dallo stesso anno fino al 1541 Szeged rimase sotto il dominio di Szapolyai.", "4317e319"]},
"OLAYLAR_EK:1532-01-01:0":{"b": ["Gli abitanti di Pécs passarono dalla parte di Szapolyai", "3fc4e7f2"], "d": ["Pécs, che nel 1528 aveva ottenuto privilegi da Ferdinando, poco dopo passò dalla parte di Szapolyai; re János nel 1533 soggiornò per un periodo in città. Con la caduta di Buda nel 1541 la città tornò dalla parte di Ferdinando.", "af03d9f3"]}
});
